const std = @import("std");
const Allocator = std.mem.Allocator;
const Tensor = @import("../core/tensor.zig").Tensor;
const memory = @import("../core/memory.zig");
const Thread = std.Thread;

pub const RSFLayerConfig = struct {
    clip_min: f32 = -5.0,
    clip_max: f32 = 5.0,
    seed_offset: u64 = 0,
    grad_mean: bool = true,
};

pub const RSFConfig = struct {
    clip_min: f32 = -5.0,
    clip_max: f32 = 5.0,
    grad_mean: bool = true,
    max_dim: usize = 1 << 20,
    max_layers: usize = 1 << 20,
};

const SAVE_VERSION: u32 = 4;

fn checkedMul(a: usize, b: usize) !usize {
    return std.math.mul(usize, a, b) catch return error.Overflow;
}

fn checkedAddU64(a: u64, b: u64) !u64 {
    return std.math.add(u64, a, b) catch return error.Overflow;
}

fn checkedMulU64(a: u64, b: u64) !u64 {
    return std.math.mul(u64, a, b) catch return error.Overflow;
}

fn checkedCastU64ToUsize(v: u64) !usize {
    if (v > @as(u64, std.math.maxInt(usize))) return error.TooLarge;
    return @intCast(v);
}

fn validateTensor2D(t: *const Tensor) !void {
    if (t.shape.dims.len != 2) return error.ShapeMismatch;
    const rows = t.shape.dims[0];
    const cols = t.shape.dims[1];
    const expected = try checkedMul(rows, cols);
    if (t.data.len != expected) return error.DataLengthMismatch;
}

fn validateTensorShape2D(t: *const Tensor, rows: usize, cols: usize) !void {
    try validateTensor2D(t);
    if (t.shape.dims[0] != rows or t.shape.dims[1] != cols) return error.ShapeMismatch;
    const expected = try checkedMul(rows, cols);
    if (t.data.len != expected) return error.DataLengthMismatch;
}

fn validateFiniteSlice(data: []const f32) !void {
    for (data) |v| {
        if (!std.math.isFinite(v)) return error.NumericFailure;
    }
}

fn countNonFinite(data: []const f32) usize {
    var count: usize = 0;
    for (data) |v| {
        if (!std.math.isFinite(v)) count += 1;
    }
    return count;
}

fn tensorsOverlap(a: *const Tensor, b: *const Tensor) bool {
    if (a.data.len == 0 or b.data.len == 0) return false;
    const a_start: usize = @intFromPtr(a.data.ptr);
    const b_start: usize = @intFromPtr(b.data.ptr);
    const a_bytes = std.math.mul(usize, a.data.len, @sizeOf(f32)) catch return true;
    const b_bytes = std.math.mul(usize, b.data.len, @sizeOf(f32)) catch return true;
    const a_end = std.math.add(usize, a_start, a_bytes) catch return true;
    const b_end = std.math.add(usize, b_start, b_bytes) catch return true;
    return a_start < b_end and b_start < a_end;
}

fn zeroSlice(data: []f32) void {
    @memset(data, 0.0);
}

fn cloneOptionalTensor(allocator: Allocator, src: ?Tensor) !?Tensor {
    if (src) |t| {
        return try t.copy(allocator);
    }
    return null;
}

fn deinitOptionalTensor(t: *?Tensor) void {
    if (t.*) |*v| {
        v.deinit();
    }
    t.* = null;
}

fn restoreOptionalTensor(dst: *?Tensor, src: *?Tensor) void {
    deinitOptionalTensor(dst);
    if (src.*) |v| {
        dst.* = v;
        src.* = null;
    } else {
        dst.* = null;
    }
}

fn lockPtr(mutex: *Thread.Mutex) void {
    mutex.lock();
}

fn unlockPtr(mutex: *Thread.Mutex) void {
    mutex.unlock();
}

const RSFLayerState = struct {
    allocator: Allocator,
    dim: usize,
    clip_min: f32,
    clip_max: f32,
    grad_mean: bool,
    deinitialized: bool,
    mutex: Thread.Mutex,
    s_weight: Tensor,
    t_weight: Tensor,
    s_bias: Tensor,
    t_bias: Tensor,
    s_weight_grad: ?Tensor,
    t_weight_grad: ?Tensor,
    s_bias_grad: ?Tensor,
    t_bias_grad: ?Tensor,
};

const LayerGradientSnapshot = struct {
    s_weight_grad: ?Tensor = null,
    t_weight_grad: ?Tensor = null,
    s_bias_grad: ?Tensor = null,
    t_bias_grad: ?Tensor = null,

    fn deinit(self: *LayerGradientSnapshot) void {
        deinitOptionalTensor(&self.s_weight_grad);
        deinitOptionalTensor(&self.t_weight_grad);
        deinitOptionalTensor(&self.s_bias_grad);
        deinitOptionalTensor(&self.t_bias_grad);
    }
};

fn validateLayerConfig(dim: usize, config: RSFLayerConfig) !void {
    if (dim == 0) return error.InvalidDimension;
    if (!std.math.isFinite(config.clip_min) or !std.math.isFinite(config.clip_max)) return error.NonFinite;
    if (!(config.clip_min < config.clip_max)) return error.InvalidConfig;
    if (config.clip_max > 20.0) return error.InvalidConfig;
    if (config.clip_min < -20.0) return error.InvalidConfig;
    _ = try checkedMul(dim, dim);
}

fn validateRSFConfig(dim: usize, num_layers: usize, cfg: RSFConfig) !void {
    if (dim == 0) return error.InvalidDimension;
    if (num_layers == 0) return error.InvalidLayerCount;
    if (dim > cfg.max_dim or num_layers > cfg.max_layers) return error.TooLarge;
    if (!std.math.isFinite(cfg.clip_min) or !std.math.isFinite(cfg.clip_max)) return error.NonFinite;
    if (!(cfg.clip_min < cfg.clip_max)) return error.InvalidConfig;
    if (cfg.clip_max > 20.0 or cfg.clip_min < -20.0) return error.InvalidConfig;
    _ = try checkedMul(dim, dim);
    _ = try checkedMul(dim, 2);
}

pub const RSFLayer = struct {
    state: ?*RSFLayerState,

    pub fn init(allocator: Allocator, dim: usize) !RSFLayer {
        return initWithConfig(allocator, dim, .{});
    }

    pub fn initWithArena(arena: *memory.ArenaAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(arena.allocator(), dim, config);
    }

    pub fn initWithPool(pool: *memory.PoolAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(pool.allocator(), dim, config);
    }

    pub fn initWithSlab(slab: *memory.SlabAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(slab.allocator(), dim, config);
    }

    pub fn initWithBuddy(buddy: *memory.BuddyAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(buddy.allocator(), dim, config);
    }

    pub fn initWithConfig(allocator: Allocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        try validateLayerConfig(dim, config);

        const fan_in: f64 = @floatFromInt(dim);
        const fan_out: f64 = @floatFromInt(dim);
        const fan_sum = fan_in + fan_out;
        if (!(fan_sum > 0.0)) return error.InvalidDimension;
        const xavier_bound: f32 = @floatCast(@sqrt(6.0 / fan_sum));

        var st = try allocator.create(RSFLayerState);
        errdefer allocator.destroy(st);

        const weight_shape = [_]usize{ dim, dim };
        const bias_shape = [_]usize{ 1, dim };
        const seed1 = try checkedAddU64(42, config.seed_offset);
        const seed2 = try checkedAddU64(43, config.seed_offset);

        var s_w = try Tensor.randomUniform(allocator, &weight_shape, -xavier_bound, xavier_bound, seed1);
        errdefer s_w.deinit();
        var t_w = try Tensor.randomUniform(allocator, &weight_shape, -xavier_bound, xavier_bound, seed2);
        errdefer t_w.deinit();
        var s_b = try Tensor.zeros(allocator, &bias_shape);
        errdefer s_b.deinit();
        var t_b = try Tensor.zeros(allocator, &bias_shape);
        errdefer t_b.deinit();

        try validateTensorShape2D(&s_w, dim, dim);
        try validateTensorShape2D(&t_w, dim, dim);
        try validateTensorShape2D(&s_b, 1, dim);
        try validateTensorShape2D(&t_b, 1, dim);
        try validateFiniteSlice(s_w.data);
        try validateFiniteSlice(t_w.data);
        try validateFiniteSlice(s_b.data);
        try validateFiniteSlice(t_b.data);

        st.* = .{
            .allocator = allocator,
            .dim = dim,
            .clip_min = config.clip_min,
            .clip_max = config.clip_max,
            .grad_mean = config.grad_mean,
            .deinitialized = false,
            .mutex = .{},
            .s_weight = s_w,
            .t_weight = t_w,
            .s_bias = s_b,
            .t_bias = t_b,
            .s_weight_grad = null,
            .t_weight_grad = null,
            .s_bias_grad = null,
            .t_bias_grad = null,
        };

        return .{ .state = st };
    }

    fn getState(self: *const RSFLayer) !*RSFLayerState {
        return self.state orelse error.NotInitialized;
    }

    fn withStateLocked(self: *const RSFLayer) !*RSFLayerState {
        const st = try self.getState();
        lockPtr(&st.mutex);
        if (st.deinitialized) {
            unlockPtr(&st.mutex);
            return error.NotInitialized;
        }
        return st;
    }

    fn validatePairLocked(st: *const RSFLayerState, a: *const Tensor, b: *const Tensor) !usize {
        try validateTensor2D(a);
        try validateTensor2D(b);
        if (tensorsOverlap(a, b)) return error.AliasedBuffers;
        if (a.shape.dims[1] != st.dim or b.shape.dims[1] != st.dim) return error.ShapeMismatch;
        if (a.shape.dims[0] != b.shape.dims[0]) return error.ShapeMismatch;
        if (st.s_bias.data.len != st.dim or st.t_bias.data.len != st.dim) return error.ShapeMismatch;
        const batch_size = a.shape.dims[0];
        if (batch_size == 0) return error.InvalidBatchSize;
        const bd = try checkedMul(batch_size, st.dim);
        if (a.data.len != bd or b.data.len != bd) return error.DataLengthMismatch;
        return batch_size;
    }

    fn validateGradPairForBatchLocked(st: *const RSFLayerState, dy1: *const Tensor, dy2: *const Tensor, batch_size: usize) !void {
        _ = st;
        try validateTensor2D(dy1);
        try validateTensor2D(dy2);
        if (tensorsOverlap(dy1, dy2)) return error.AliasedBuffers;
        if (dy1.shape.dims[0] != batch_size or dy2.shape.dims[0] != batch_size) return error.ShapeMismatch;
        if (dy1.shape.dims[1] != dy2.shape.dims[1]) return error.ShapeMismatch;
        const bd = try checkedMul(batch_size, dy1.shape.dims[1]);
        if (dy1.data.len != bd or dy2.data.len != bd) return error.DataLengthMismatch;
    }

    fn ensureNoOverlapBackward(
        y1: *const Tensor,
        y2: *const Tensor,
        dy1: *const Tensor,
        dy2: *const Tensor,
        x1_out: *const Tensor,
        x2_out: *const Tensor,
        dx1_out: *const Tensor,
        dx2_out: *const Tensor,
    ) !void {
        if (tensorsOverlap(x1_out, x2_out)) return error.AliasedBuffers;
        if (tensorsOverlap(x1_out, dx1_out)) return error.AliasedBuffers;
        if (tensorsOverlap(x1_out, dx2_out)) return error.AliasedBuffers;
        if (tensorsOverlap(x2_out, dx1_out)) return error.AliasedBuffers;
        if (tensorsOverlap(x2_out, dx2_out)) return error.AliasedBuffers;
        if (tensorsOverlap(dx1_out, dx2_out)) return error.AliasedBuffers;

        if (tensorsOverlap(x1_out, y1) or tensorsOverlap(x1_out, y2) or tensorsOverlap(x1_out, dy1) or tensorsOverlap(x1_out, dy2)) return error.AliasedBuffers;
        if (tensorsOverlap(x2_out, y1) or tensorsOverlap(x2_out, y2) or tensorsOverlap(x2_out, dy1) or tensorsOverlap(x2_out, dy2)) return error.AliasedBuffers;
        if (tensorsOverlap(dx1_out, y1) or tensorsOverlap(dx1_out, y2) or tensorsOverlap(dx1_out, dy1) or tensorsOverlap(dx1_out, dy2)) return error.AliasedBuffers;
        if (tensorsOverlap(dx2_out, y1) or tensorsOverlap(dx2_out, y2) or tensorsOverlap(dx2_out, dy1) or tensorsOverlap(dx2_out, dy2)) return error.AliasedBuffers;
    }

    fn ensureGradientsLocked(st: *RSFLayerState) !void {
        const need_swg = st.s_weight_grad == null;
        const need_twg = st.t_weight_grad == null;
        const need_sbg = st.s_bias_grad == null;
        const need_tbg = st.t_bias_grad == null;

        if (!(need_swg or need_twg or need_sbg or need_tbg)) return;

        const weight_shape = [_]usize{ st.dim, st.dim };
        const bias_shape = [_]usize{ 1, st.dim };

        var swg_new: ?Tensor = null;
        var twg_new: ?Tensor = null;
        var sbg_new: ?Tensor = null;
        var tbg_new: ?Tensor = null;

        errdefer {
            deinitOptionalTensor(&swg_new);
            deinitOptionalTensor(&twg_new);
            deinitOptionalTensor(&sbg_new);
            deinitOptionalTensor(&tbg_new);
        }

        if (need_swg) swg_new = try Tensor.zeros(st.allocator, &weight_shape);
        if (need_twg) twg_new = try Tensor.zeros(st.allocator, &weight_shape);
        if (need_sbg) sbg_new = try Tensor.zeros(st.allocator, &bias_shape);
        if (need_tbg) tbg_new = try Tensor.zeros(st.allocator, &bias_shape);

        if (swg_new) |v| {
            st.s_weight_grad = v;
            swg_new = null;
        }
        if (twg_new) |v| {
            st.t_weight_grad = v;
            twg_new = null;
        }
        if (sbg_new) |v| {
            st.s_bias_grad = v;
            sbg_new = null;
        }
        if (tbg_new) |v| {
            st.t_bias_grad = v;
            tbg_new = null;
        }
    }

    pub fn ensureGradients(self: *RSFLayer) !void {
        const st = try self.withStateLocked();
        defer unlockPtr(&st.mutex);
        try ensureGradientsLocked(st);
    }

    pub fn zeroGradients(self: *RSFLayer) void {
        const st = self.withStateLocked() catch return;
        defer unlockPtr(&st.mutex);

        if (st.s_weight_grad) |*g| zeroSlice(g.data);
        if (st.t_weight_grad) |*g| zeroSlice(g.data);
        if (st.s_bias_grad) |*g| zeroSlice(g.data);
        if (st.t_bias_grad) |*g| zeroSlice(g.data);
    }

    fn snapshotGradients(self: *RSFLayer) !LayerGradientSnapshot {
        const st = try self.withStateLocked();
        defer unlockPtr(&st.mutex);

        var snap = LayerGradientSnapshot{};
        errdefer snap.deinit();

        snap.s_weight_grad = try cloneOptionalTensor(st.allocator, st.s_weight_grad);
        snap.t_weight_grad = try cloneOptionalTensor(st.allocator, st.t_weight_grad);
        snap.s_bias_grad = try cloneOptionalTensor(st.allocator, st.s_bias_grad);
        snap.t_bias_grad = try cloneOptionalTensor(st.allocator, st.t_bias_grad);

        return snap;
    }

    fn restoreGradients(self: *RSFLayer, snap: *LayerGradientSnapshot) !void {
        const st = try self.withStateLocked();
        defer unlockPtr(&st.mutex);

        restoreOptionalTensor(&st.s_weight_grad, &snap.s_weight_grad);
        restoreOptionalTensor(&st.t_weight_grad, &snap.t_weight_grad);
        restoreOptionalTensor(&st.s_bias_grad, &snap.s_bias_grad);
        restoreOptionalTensor(&st.t_bias_grad, &snap.t_bias_grad);
    }

    fn computeScaleBuffersLocked(
        st: *const RSFLayerState,
        x2: *const Tensor,
        batch_size: usize,
        scale_pre: []f32,
        scale_exp: []f32,
    ) !void {
        try validateTensorShape2D(x2, batch_size, st.dim);
        try validateFiniteSlice(x2.data);
        try validateFiniteSlice(st.s_weight.data);
        try validateFiniteSlice(st.s_bias.data);

        const bd = try checkedMul(batch_size, st.dim);
        if (scale_pre.len != bd or scale_exp.len != bd) return error.DataLengthMismatch;

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            const x_row = x2.data[b * st.dim .. (b + 1) * st.dim];
            var o: usize = 0;
            while (o < st.dim) : (o += 1) {
                var acc: f32 = st.s_bias.data[o];
                const w_row = st.s_weight.data[o * st.dim .. (o + 1) * st.dim];
                var i: usize = 0;
                while (i < st.dim) : (i += 1) {
                    const v = acc + w_row[i] * x_row[i];
                    if (!std.math.isFinite(v)) return error.NumericFailure;
                    acc = v;
                }
                scale_pre[b * st.dim + o] = acc;
                const clipped = std.math.clamp(acc, st.clip_min, st.clip_max);
                const ev = @exp(clipped);
                if (!std.math.isFinite(ev)) return error.NumericFailure;
                scale_exp[b * st.dim + o] = ev;
            }
        }
    }

    fn computeTranslationBufferLocked(
        st: *const RSFLayerState,
        x1: *const Tensor,
        batch_size: usize,
        trans: []f32,
    ) !void {
        try validateTensorShape2D(x1, batch_size, st.dim);
        try validateFiniteSlice(x1.data);
        try validateFiniteSlice(st.t_weight.data);
        try validateFiniteSlice(st.t_bias.data);

        const bd = try checkedMul(batch_size, st.dim);
        if (trans.len != bd) return error.DataLengthMismatch;

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            const x_row = x1.data[b * st.dim .. (b + 1) * st.dim];
            var o: usize = 0;
            while (o < st.dim) : (o += 1) {
                var acc: f32 = st.t_bias.data[o];
                const w_row = st.t_weight.data[o * st.dim .. (o + 1) * st.dim];
                var i: usize = 0;
                while (i < st.dim) : (i += 1) {
                    const v = acc + w_row[i] * x_row[i];
                    if (!std.math.isFinite(v)) return error.NumericFailure;
                    acc = v;
                }
                trans[b * st.dim + o] = acc;
            }
        }
    }

    fn forwardLocked(st: *const RSFLayerState, x1: *Tensor, x2: *Tensor) !void {
        const batch_size = try validatePairLocked(st, x1, x2);
        const bd = try checkedMul(batch_size, st.dim);

        var scale_pre = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_pre);
        var scale_exp = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_exp);
        var trans = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(trans);

        try computeScaleBuffersLocked(st, x2, batch_size, scale_pre, scale_exp);
        var i: usize = 0;
        while (i < bd) : (i += 1) {
            const v = x1.data[i] * scale_exp[i];
            if (!std.math.isFinite(v)) return error.NumericFailure;
            x1.data[i] = v;
        }

        try computeTranslationBufferLocked(st, x1, batch_size, trans);
        i = 0;
        while (i < bd) : (i += 1) {
            const v = x2.data[i] + trans[i];
            if (!std.math.isFinite(v)) return error.NumericFailure;
            x2.data[i] = v;
        }

        if (countNonFinite(x1.data) > 0 or countNonFinite(x2.data) > 0) return error.NumericFailure;
    }

    fn inverseLocked(st: *const RSFLayerState, y1: *Tensor, y2: *Tensor) !void {
        const batch_size = try validatePairLocked(st, y1, y2);
        const bd = try checkedMul(batch_size, st.dim);

        var trans = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(trans);
        var scale_pre = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_pre);
        var scale_exp = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_exp);

        try computeTranslationBufferLocked(st, y1, batch_size, trans);
        var i: usize = 0;
        while (i < bd) : (i += 1) {
            const v = y2.data[i] - trans[i];
            if (!std.math.isFinite(v)) return error.NumericFailure;
            y2.data[i] = v;
        }

        try computeScaleBuffersLocked(st, y2, batch_size, scale_pre, scale_exp);
        i = 0;
        while (i < bd) : (i += 1) {
            const v = y1.data[i] / scale_exp[i];
            if (!std.math.isFinite(v)) return error.NumericFailure;
            y1.data[i] = v;
        }

        if (countNonFinite(y1.data) > 0 or countNonFinite(y2.data) > 0) return error.NumericFailure;
    }

    fn backwardFromInputsLocked(
        st: *RSFLayerState,
        x1_in: *const Tensor,
        x2_in: *const Tensor,
        dy1_in: *const Tensor,
        dy2_in: *const Tensor,
        dx1_out: *Tensor,
        dx2_out: *Tensor,
    ) !void {
        const batch_size = try validatePairLocked(st, x1_in, x2_in);
        try validateGradPairForBatchLocked(st, dy1_in, dy2_in, batch_size);
        try validateTensorShape2D(dx1_out, batch_size, st.dim);
        try validateTensorShape2D(dx2_out, batch_size, st.dim);

        if (tensorsOverlap(dx1_out, dx2_out)) return error.AliasedBuffers;
        if (tensorsOverlap(dx1_out, x1_in) or tensorsOverlap(dx1_out, x2_in) or tensorsOverlap(dx1_out, dy1_in) or tensorsOverlap(dx1_out, dy2_in)) return error.AliasedBuffers;
        if (tensorsOverlap(dx2_out, x1_in) or tensorsOverlap(dx2_out, x2_in) or tensorsOverlap(dx2_out, dy1_in) or tensorsOverlap(dx2_out, dy2_in)) return error.AliasedBuffers;

        try validateFiniteSlice(x1_in.data);
        try validateFiniteSlice(x2_in.data);
        try validateFiniteSlice(dy1_in.data);
        try validateFiniteSlice(dy2_in.data);
        try validateFiniteSlice(st.s_weight.data);
        try validateFiniteSlice(st.t_weight.data);
        try validateFiniteSlice(st.s_bias.data);
        try validateFiniteSlice(st.t_bias.data);

        try ensureGradientsLocked(st);

        const bd = try checkedMul(batch_size, st.dim);
        const grad_scale: f32 = if (st.grad_mean) blk: {
            const bs_f = @as(f32, @floatFromInt(batch_size));
            const gs = 1.0 / bs_f;
            if (!std.math.isFinite(gs)) break :blk 1.0;
            break :blk gs;
        } else 1.0;

        var scale_pre = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_pre);
        var scale_exp = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_exp);
        var y1_buf = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(y1_buf);
        var dy1_total = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(dy1_total);
        var ds = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(ds);

        try computeScaleBuffersLocked(st, x2_in, batch_size, scale_pre, scale_exp);

        var i: usize = 0;
        while (i < bd) : (i += 1) {
            const yv = x1_in.data[i] * scale_exp[i];
            if (!std.math.isFinite(yv)) return error.NumericFailure;
            y1_buf[i] = yv;
        }

        if (st.t_weight_grad) |*twg| {
            if (twg.data.len != try checkedMul(st.dim, st.dim)) return error.DataLengthMismatch;
            var o: usize = 0;
            while (o < st.dim) : (o += 1) {
                var ii: usize = 0;
                while (ii < st.dim) : (ii += 1) {
                    var acc: f32 = 0.0;
                    var b: usize = 0;
                    while (b < batch_size) : (b += 1) {
                        const v = acc + dy2_in.data[b * st.dim + o] * y1_buf[b * st.dim + ii];
                        if (!std.math.isFinite(v)) return error.NumericFailure;
                        acc = v;
                    }
                    const scaled = acc * grad_scale;
                    if (!std.math.isFinite(scaled)) return error.NumericFailure;
                    const idx = o * st.dim + ii;
                    const nv = twg.data[idx] + scaled;
                    if (!std.math.isFinite(nv)) return error.NumericFailure;
                    twg.data[idx] = nv;
                }
            }
        }

        if (st.t_bias_grad) |*tbg| {
            if (tbg.data.len != st.dim) return error.DataLengthMismatch;
            var o: usize = 0;
            while (o < st.dim) : (o += 1) {
                var acc: f32 = 0.0;
                var b: usize = 0;
                while (b < batch_size) : (b += 1) {
                    const v = acc + dy2_in.data[b * st.dim + o];
                    if (!std.math.isFinite(v)) return error.NumericFailure;
                    acc = v;
                }
                const scaled = acc * grad_scale;
                if (!std.math.isFinite(scaled)) return error.NumericFailure;
                const nv = tbg.data[o] + scaled;
                if (!std.math.isFinite(nv)) return error.NumericFailure;
                tbg.data[o] = nv;
            }
        }

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            var ii: usize = 0;
            while (ii < st.dim) : (ii += 1) {
                var acc = dy1_in.data[b * st.dim + ii];
                var o: usize = 0;
                while (o < st.dim) : (o += 1) {
                    const v = acc + dy2_in.data[b * st.dim + o] * st.t_weight.data[o * st.dim + ii];
                    if (!std.math.isFinite(v)) return error.NumericFailure;
                    acc = v;
                }
                dy1_total[b * st.dim + ii] = acc;
            }
        }

        i = 0;
        while (i < bd) : (i += 1) {
            const v = dy1_total[i] * scale_exp[i];
            if (!std.math.isFinite(v)) return error.NumericFailure;
            dx1_out.data[i] = v;
        }

        i = 0;
        while (i < bd) : (i += 1) {
            const s_val = scale_pre[i];
            if (!std.math.isFinite(s_val)) return error.NumericFailure;
            if (s_val < st.clip_min or s_val > st.clip_max) {
                ds[i] = 0.0;
                continue;
            }
            const dscale_val = dy1_total[i] * x1_in.data[i];
            if (!std.math.isFinite(dscale_val)) return error.NumericFailure;
            const ds_val = dscale_val * scale_exp[i];
            if (!std.math.isFinite(ds_val)) return error.NumericFailure;
            ds[i] = ds_val;
        }

        if (st.s_weight_grad) |*swg| {
            if (swg.data.len != try checkedMul(st.dim, st.dim)) return error.DataLengthMismatch;
            var o: usize = 0;
            while (o < st.dim) : (o += 1) {
                var ii: usize = 0;
                while (ii < st.dim) : (ii += 1) {
                    var acc: f32 = 0.0;
                    var bb: usize = 0;
                    while (bb < batch_size) : (bb += 1) {
                        const v = acc + ds[bb * st.dim + o] * x2_in.data[bb * st.dim + ii];
                        if (!std.math.isFinite(v)) return error.NumericFailure;
                        acc = v;
                    }
                    const scaled = acc * grad_scale;
                    if (!std.math.isFinite(scaled)) return error.NumericFailure;
                    const idx = o * st.dim + ii;
                    const nv = swg.data[idx] + scaled;
                    if (!std.math.isFinite(nv)) return error.NumericFailure;
                    swg.data[idx] = nv;
                }
            }
        }

        if (st.s_bias_grad) |*sbg| {
            if (sbg.data.len != st.dim) return error.DataLengthMismatch;
            var o: usize = 0;
            while (o < st.dim) : (o += 1) {
                var acc: f32 = 0.0;
                var bb: usize = 0;
                while (bb < batch_size) : (bb += 1) {
                    const v = acc + ds[bb * st.dim + o];
                    if (!std.math.isFinite(v)) return error.NumericFailure;
                    acc = v;
                }
                const scaled = acc * grad_scale;
                if (!std.math.isFinite(scaled)) return error.NumericFailure;
                const nv = sbg.data[o] + scaled;
                if (!std.math.isFinite(nv)) return error.NumericFailure;
                sbg.data[o] = nv;
            }
        }

        b = 0;
        while (b < batch_size) : (b += 1) {
            var ii: usize = 0;
            while (ii < st.dim) : (ii += 1) {
                var acc = dy2_in.data[b * st.dim + ii];
                var o: usize = 0;
                while (o < st.dim) : (o += 1) {
                    const v = acc + ds[b * st.dim + o] * st.s_weight.data[o * st.dim + ii];
                    if (!std.math.isFinite(v)) return error.NumericFailure;
                    acc = v;
                }
                dx2_out.data[b * st.dim + ii] = acc;
            }
        }

        if (countNonFinite(dx1_out.data) > 0 or countNonFinite(dx2_out.data) > 0) return error.NumericFailure;
    }

    pub fn forward(self: *const RSFLayer, x1: *Tensor, x2: *Tensor) !void {
        const st = try self.withStateLocked();
        defer unlockPtr(&st.mutex);
        try forwardLocked(st, x1, x2);
    }

    pub fn inverse(self: *const RSFLayer, y1: *Tensor, y2: *Tensor) !void {
        const st = try self.withStateLocked();
        defer unlockPtr(&st.mutex);
        try inverseLocked(st, y1, y2);
    }

    pub fn backward(
        self: *RSFLayer,
        y1: *const Tensor,
        y2: *const Tensor,
        dy1_in: *const Tensor,
        dy2_in: *const Tensor,
        x1_out: *Tensor,
        x2_out: *Tensor,
        dx1_out: *Tensor,
        dx2_out: *Tensor,
    ) !void {
        const st = try self.withStateLocked();
        defer unlockPtr(&st.mutex);

        const batch_size = try validatePairLocked(st, y1, y2);
        try validateGradPairForBatchLocked(st, dy1_in, dy2_in, batch_size);
        try validateTensorShape2D(x1_out, batch_size, st.dim);
        try validateTensorShape2D(x2_out, batch_size, st.dim);
        try validateTensorShape2D(dx1_out, batch_size, st.dim);
        try validateTensorShape2D(dx2_out, batch_size, st.dim);
        try ensureNoOverlapBackward(y1, y2, dy1_in, dy2_in, x1_out, x2_out, dx1_out, dx2_out);

        const bd = try checkedMul(batch_size, st.dim);

        var trans = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(trans);
        var scale_pre = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_pre);
        var scale_exp = try st.allocator.alloc(f32, bd);
        defer st.allocator.free(scale_exp);

        try computeTranslationBufferLocked(st, y1, batch_size, trans);
        var i: usize = 0;
        while (i < bd) : (i += 1) {
            const v = y2.data[i] - trans[i];
            if (!std.math.isFinite(v)) return error.NumericFailure;
            x2_out.data[i] = v;
        }

        try computeScaleBuffersLocked(st, x2_out, batch_size, scale_pre, scale_exp);
        i = 0;
        while (i < bd) : (i += 1) {
            const v = y1.data[i] / scale_exp[i];
            if (!std.math.isFinite(v)) return error.NumericFailure;
            x1_out.data[i] = v;
        }

        try backwardFromInputsLocked(st, x1_out, x2_out, dy1_in, dy2_in, dx1_out, dx2_out);
    }

    pub fn deinit(self: *RSFLayer) void {
        const st = self.state orelse return;
        self.state = null;

        lockPtr(&st.mutex);
        defer unlockPtr(&st.mutex);

        if (st.deinitialized) return;

        st.s_weight.deinit();
        st.t_weight.deinit();
        st.s_bias.deinit();
        st.t_bias.deinit();
        deinitOptionalTensor(&st.s_weight_grad);
        deinitOptionalTensor(&st.t_weight_grad);
        deinitOptionalTensor(&st.s_bias_grad);
        deinitOptionalTensor(&st.t_bias_grad);
        st.deinitialized = true;
    }
};

const ControlBlock = struct {
    allocator: Allocator,
    dim: usize,
    num_layers: usize,
    cfg: RSFConfig,
    layers: []RSFLayer,
    model_lock: Thread.RwLock,
    lifecycle_mutex: Thread.Mutex,
    lifecycle_cond: Thread.Condition,
    active_ops: usize,
    deinitialized: bool,
    deiniting: bool,
};

pub const RSF = struct {
    ctrl: ?*ControlBlock,

    pub fn init(allocator: Allocator, dim: usize, num_layers: usize) !RSF {
        return initWithConfig(allocator, dim, num_layers, .{});
    }

    pub fn initWithConfig(allocator: Allocator, dim: usize, num_layers: usize, cfg: RSFConfig) !RSF {
        try validateRSFConfig(dim, num_layers, cfg);

        var c = try allocator.create(ControlBlock);
        errdefer allocator.destroy(c);

        var layers = try allocator.alloc(RSFLayer, num_layers);
        errdefer allocator.free(layers);

        var initialized: usize = 0;
        errdefer {
            var i: usize = 0;
            while (i < initialized) : (i += 1) {
                layers[i].deinit();
            }
        }

        var i: usize = 0;
        while (i < num_layers) : (i += 1) {
            const seed_base = try checkedMulU64(@as(u64, @intCast(i)), 10007);
            layers[i] = try RSFLayer.initWithConfig(allocator, dim, .{
                .clip_min = cfg.clip_min,
                .clip_max = cfg.clip_max,
                .seed_offset = seed_base,
                .grad_mean = cfg.grad_mean,
            });
            initialized += 1;
        }

        c.* = .{
            .allocator = allocator,
            .dim = dim,
            .num_layers = num_layers,
            .cfg = cfg,
            .layers = layers,
            .model_lock = .{},
            .lifecycle_mutex = .{},
            .lifecycle_cond = .{},
            .active_ops = 0,
            .deinitialized = false,
            .deiniting = false,
        };

        return .{ .ctrl = c };
    }

    fn beginShared(self: *const RSF) !*ControlBlock {
        const c = self.ctrl orelse return error.NotInitialized;

        lockPtr(&c.lifecycle_mutex);
        if (c.deinitialized or c.deiniting) {
            unlockPtr(&c.lifecycle_mutex);
            return error.NotInitialized;
        }
        c.active_ops += 1;
        unlockPtr(&c.lifecycle_mutex);

        c.model_lock.lockShared();
        return c;
    }

    fn endShared(c: *ControlBlock) void {
        c.model_lock.unlockShared();
        lockPtr(&c.lifecycle_mutex);
        c.active_ops -= 1;
        if (c.deiniting and c.active_ops == 0) c.lifecycle_cond.broadcast();
        unlockPtr(&c.lifecycle_mutex);
    }

    fn beginExclusive(self: *const RSF) !*ControlBlock {
        const c = self.ctrl orelse return error.NotInitialized;

        lockPtr(&c.lifecycle_mutex);
        if (c.deinitialized or c.deiniting) {
            unlockPtr(&c.lifecycle_mutex);
            return error.NotInitialized;
        }
        c.active_ops += 1;
        unlockPtr(&c.lifecycle_mutex);

        c.model_lock.lock();
        return c;
    }

    fn endExclusive(c: *ControlBlock) void {
        c.model_lock.unlock();
        lockPtr(&c.lifecycle_mutex);
        c.active_ops -= 1;
        if (c.deiniting and c.active_ops == 0) c.lifecycle_cond.broadcast();
        unlockPtr(&c.lifecycle_mutex);
    }

    pub fn deinit(self: *RSF) void {
        const c = self.ctrl orelse return;
        self.ctrl = null;

        lockPtr(&c.lifecycle_mutex);
        if (c.deinitialized or c.deiniting) {
            unlockPtr(&c.lifecycle_mutex);
            return;
        }
        c.deiniting = true;
        while (c.active_ops != 0) {
            c.lifecycle_cond.wait(&c.lifecycle_mutex);
        }
        unlockPtr(&c.lifecycle_mutex);

        c.model_lock.lock();
        defer c.model_lock.unlock();

        if (c.deinitialized) {
            lockPtr(&c.lifecycle_mutex);
            c.deiniting = false;
            c.lifecycle_cond.broadcast();
            unlockPtr(&c.lifecycle_mutex);
            return;
        }

        var i: usize = 0;
        while (i < c.num_layers) : (i += 1) {
            c.layers[i].deinit();
        }
        c.allocator.free(c.layers);
        c.layers = &.{};
        c.num_layers = 0;
        c.dim = 0;
        c.deinitialized = true;

        lockPtr(&c.lifecycle_mutex);
        c.deiniting = false;
        c.lifecycle_cond.broadcast();
        unlockPtr(&c.lifecycle_mutex);
    }

    fn splitInto(ctrl: *const ControlBlock, x: *const Tensor, x1: *Tensor, x2: *Tensor) !usize {
        try validateTensor2D(x);
        const dim2 = try checkedMul(ctrl.dim, 2);
        if (x.shape.dims[1] != dim2) return error.ShapeMismatch;
        const batch_size = x.shape.dims[0];
        if (batch_size == 0) return error.InvalidBatchSize;

        try validateTensorShape2D(x1, batch_size, ctrl.dim);
        try validateTensorShape2D(x2, batch_size, ctrl.dim);

        if (tensorsOverlap(x, x1) or tensorsOverlap(x, x2) or tensorsOverlap(x1, x2)) return error.AliasedBuffers;

        const bd = try checkedMul(batch_size, ctrl.dim);
        if (x1.data.len != bd or x2.data.len != bd) return error.DataLengthMismatch;

        const bd2 = try checkedMul(batch_size, dim2);
        if (x.data.len != bd2) return error.DataLengthMismatch;

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            const src_offset = b * dim2;
            const dst_offset = b * ctrl.dim;
            @memcpy(x1.data[dst_offset .. dst_offset + ctrl.dim], x.data[src_offset .. src_offset + ctrl.dim]);
            @memcpy(x2.data[dst_offset .. dst_offset + ctrl.dim], x.data[src_offset + ctrl.dim .. src_offset + dim2]);
        }

        return batch_size;
    }

    fn mergeFrom(ctrl: *const ControlBlock, x1: *const Tensor, x2: *const Tensor, out: *Tensor) !void {
        try validateTensor2D(out);
        try validateTensor2D(x1);
        try validateTensor2D(x2);
        if (x1.shape.dims[0] != x2.shape.dims[0]) return error.ShapeMismatch;
        if (x1.shape.dims[1] != ctrl.dim or x2.shape.dims[1] != ctrl.dim) return error.ShapeMismatch;

        if (tensorsOverlap(out, x1) or tensorsOverlap(out, x2) or tensorsOverlap(x1, x2)) return error.AliasedBuffers;

        const dim2 = try checkedMul(ctrl.dim, 2);
        if (out.shape.dims[0] != x1.shape.dims[0] or out.shape.dims[1] != dim2) return error.ShapeMismatch;

        const batch_size = x1.shape.dims[0];
        const bd = try checkedMul(batch_size, ctrl.dim);
        if (x1.data.len != bd or x2.data.len != bd) return error.DataLengthMismatch;

        const bd2 = try checkedMul(batch_size, dim2);
        if (out.data.len != bd2) return error.DataLengthMismatch;

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            const src_offset = b * ctrl.dim;
            const dst_offset = b * dim2;
            @memcpy(out.data[dst_offset .. dst_offset + ctrl.dim], x1.data[src_offset .. src_offset + ctrl.dim]);
            @memcpy(out.data[dst_offset + ctrl.dim .. dst_offset + dim2], x2.data[src_offset .. src_offset + ctrl.dim]);
        }
    }

    fn forwardOnCPU(ctrl: *ControlBlock, x: *Tensor) !void {
        try validateTensor2D(x);
        const dim2 = try checkedMul(ctrl.dim, 2);
        if (x.shape.dims[1] != dim2) return error.ShapeMismatch;

        const batch_size = x.shape.dims[0];
        if (batch_size == 0) return error.InvalidBatchSize;

        var shape_half = [_]usize{ batch_size, ctrl.dim };
        var x1 = try Tensor.init(ctrl.allocator, &shape_half);
        defer x1.deinit();
        var x2 = try Tensor.init(ctrl.allocator, &shape_half);
        defer x2.deinit();

        _ = try splitInto(ctrl, x, &x1, &x2);

        var i: usize = 0;
        while (i < ctrl.num_layers) : (i += 1) {
            try ctrl.layers[i].forward(&x1, &x2);
        }

        try mergeFrom(ctrl, &x1, &x2, x);

        if (countNonFinite(x.data) > 0) return error.NumericFailure;
    }

    pub fn isGPUAvailable(self: *const RSF) bool {
        _ = self;
        return false;
    }

    pub fn syncWeightsToGPU(self: *RSF) !void {
        _ = self;
        return error.GPUUnavailable;
    }

    pub fn zeroGradients(self: *RSF) !void {
        const c = try self.beginExclusive();
        defer endExclusive(c);

        var i: usize = 0;
        while (i < c.num_layers) : (i += 1) {
            c.layers[i].zeroGradients();
        }
    }

    pub fn forwardCPU(self: *RSF, x: *Tensor) !void {
        return self.forward(x);
    }

    pub fn forward(self: *RSF, x: *Tensor) !void {
        const c = try self.beginShared();
        defer endShared(c);
        try forwardOnCPU(c, x);
    }

    pub fn inverse(self: *RSF, y: *Tensor) !void {
        const c = try self.beginShared();
        defer endShared(c);

        try validateTensor2D(y);
        const dim2 = try checkedMul(c.dim, 2);
        if (y.shape.dims[1] != dim2) return error.ShapeMismatch;

        const batch_size = y.shape.dims[0];
        if (batch_size == 0) return error.InvalidBatchSize;

        var shape_half = [_]usize{ batch_size, c.dim };
        var y1 = try Tensor.init(c.allocator, &shape_half);
        defer y1.deinit();
        var y2 = try Tensor.init(c.allocator, &shape_half);
        defer y2.deinit();

        _ = try splitInto(c, y, &y1, &y2);

        var idx = c.num_layers;
        while (idx > 0) : (idx -= 1) {
            try c.layers[idx - 1].inverse(&y1, &y2);
        }

        try mergeFrom(c, &y1, &y2, y);

        if (countNonFinite(y.data) > 0) return error.NumericFailure;
    }

    pub fn backward(self: *RSF, grad_output: *const Tensor, input: *const Tensor, grad_input_out: *Tensor) !void {
        const c = try self.beginExclusive();
        defer endExclusive(c);

        try validateTensor2D(grad_output);
        try validateTensor2D(input);
        try validateTensor2D(grad_input_out);

        const dim2 = try checkedMul(c.dim, 2);
        if (input.shape.dims[1] != dim2) return error.ShapeMismatch;
        if (grad_output.shape.dims[0] != input.shape.dims[0] or grad_output.shape.dims[1] != input.shape.dims[1]) return error.ShapeMismatch;
        if (grad_input_out.shape.dims[0] != input.shape.dims[0] or grad_input_out.shape.dims[1] != input.shape.dims[1]) return error.ShapeMismatch;
        if (grad_input_out.data.len != input.data.len) return error.DataLengthMismatch;
        if (tensorsOverlap(grad_output, grad_input_out) or tensorsOverlap(input, grad_input_out)) return error.AliasedBuffers;

        try validateFiniteSlice(grad_output.data);
        try validateFiniteSlice(input.data);

        const batch_size = input.shape.dims[0];
        if (batch_size == 0) return error.InvalidBatchSize;

        var shape_half = [_]usize{ batch_size, c.dim };

        var acts_x1 = try c.allocator.alloc(Tensor, c.num_layers + 1);
        defer c.allocator.free(acts_x1);
        var acts_x2 = try c.allocator.alloc(Tensor, c.num_layers + 1);
        defer c.allocator.free(acts_x2);

        var act_count: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < act_count) : (j += 1) {
                acts_x1[j].deinit();
                acts_x2[j].deinit();
            }
        }

        acts_x1[0] = try Tensor.init(c.allocator, &shape_half);
        acts_x2[0] = try Tensor.init(c.allocator, &shape_half);
        act_count = 1;

        _ = try splitInto(c, input, &acts_x1[0], &acts_x2[0]);

        var l: usize = 0;
        while (l < c.num_layers) : (l += 1) {
            acts_x1[l + 1] = try acts_x1[l].copy(c.allocator);
            errdefer acts_x1[l + 1].deinit();
            acts_x2[l + 1] = try acts_x2[l].copy(c.allocator);
            errdefer acts_x2[l + 1].deinit();
            act_count += 1;
            try c.layers[l].forward(&acts_x1[l + 1], &acts_x2[l + 1]);
        }

        var dy1 = try Tensor.init(c.allocator, &shape_half);
        defer dy1.deinit();
        var dy2 = try Tensor.init(c.allocator, &shape_half);
        defer dy2.deinit();
        _ = try splitInto(c, grad_output, &dy1, &dy2);

        var cur_dy1 = try dy1.copy(c.allocator);
        defer cur_dy1.deinit();
        var cur_dy2 = try dy2.copy(c.allocator);
        defer cur_dy2.deinit();

        var prev_dx1 = try Tensor.init(c.allocator, &shape_half);
        defer prev_dx1.deinit();
        var prev_dx2 = try Tensor.init(c.allocator, &shape_half);
        defer prev_dx2.deinit();

        var snapshots = try c.allocator.alloc(LayerGradientSnapshot, c.num_layers);
        defer c.allocator.free(snapshots);

        l = 0;
        while (l < c.num_layers) : (l += 1) {
            snapshots[l] = .{};
        }
        defer {
            var j: usize = 0;
            while (j < c.num_layers) : (j += 1) {
                snapshots[j].deinit();
            }
        }

        l = 0;
        while (l < c.num_layers) : (l += 1) {
            snapshots[l] = try c.layers[l].snapshotGradients();
        }

        errdefer {
            var j: usize = 0;
            while (j < c.num_layers) : (j += 1) {
                c.layers[j].restoreGradients(&snapshots[j]) catch {};
            }
        }

        l = 0;
        while (l < c.num_layers) : (l += 1) {
            try c.layers[l].ensureGradients();
        }

        var idx = c.num_layers;
        while (idx > 0) : (idx -= 1) {
            const layer = &c.layers[idx - 1];
            const st = try layer.withStateLocked();
            defer unlockPtr(&st.mutex);
            try backwardFromInputsLocked(st, &acts_x1[idx - 1], &acts_x2[idx - 1], &cur_dy1, &cur_dy2, &prev_dx1, &prev_dx2);
            std.mem.swap(Tensor, &cur_dy1, &prev_dx1);
            std.mem.swap(Tensor, &cur_dy2, &prev_dx2);
        }

        try mergeFrom(c, &cur_dy1, &cur_dy2, grad_input_out);
        if (countNonFinite(grad_input_out.data) > 0) return error.NumericFailure;
    }

    pub fn save(self: *const RSF, path: []const u8) !void {
        const c = try self.beginShared();
        defer endShared(c);

        var parent_dir = std.fs.cwd();
        var parent_dir_needs_close = false;
        defer if (parent_dir_needs_close) parent_dir.close();

        const base_name: []const u8 = if (std.fs.path.dirname(path)) |dirname| blk: {
            parent_dir = try std.fs.cwd().openDir(dirname, .{});
            parent_dir_needs_close = true;
            break :blk std.fs.path.basename(path);
        } else path;

        var rand_bytes: [16]u8 = undefined;
        std.crypto.random.bytes(&rand_bytes);
        var rand_hex: [32]u8 = undefined;
        bytesToHexLower(&rand_hex, &rand_bytes);

        const pid: u64 = @intCast(std.os.linux.getpid());
        const ts = std.time.nanoTimestamp();
        const abs_ts: u64 = if (ts < 0) 0 else @intCast(ts);

        var tmp_name_buf: [512]u8 = undefined;
        const tmp_name = try std.fmt.bufPrint(&tmp_name_buf, "{s}.tmp.{d}.{d}.{s}", .{ base_name, pid, abs_ts, rand_hex[0..] });

        var file = try parent_dir.createFile(tmp_name, .{ .read = true, .truncate = true, .mode = 0o600 });
        var file_closed = false;
        errdefer {
            if (!file_closed) file.close();
            parent_dir.deleteFile(tmp_name) catch {};
        }

        var buffered = std.io.bufferedWriter(file.writer());
        const w = buffered.writer();
        var hasher = std.hash.Crc32.init();

        try writeBytesHashed(w, &hasher, "RSF0");
        try writeIntHashed(u32, w, &hasher, SAVE_VERSION);
        try writeIntHashed(u64, w, &hasher, @intCast(c.num_layers));
        try writeIntHashed(u64, w, &hasher, @intCast(c.dim));

        try writeF32BitsHashed(w, &hasher, c.cfg.clip_min);
        try writeF32BitsHashed(w, &hasher, c.cfg.clip_max);
        try writeByteHashed(w, &hasher, if (c.cfg.grad_mean) 1 else 0);
        try writeIntHashed(u64, w, &hasher, @intCast(c.cfg.max_dim));
        try writeIntHashed(u64, w, &hasher, @intCast(c.cfg.max_layers));

        var i: usize = 0;
        while (i < c.num_layers) : (i += 1) {
            const st = try c.layers[i].withStateLocked();
            defer unlockPtr(&st.mutex);

            try writeF32BitsHashed(w, &hasher, st.clip_min);
            try writeF32BitsHashed(w, &hasher, st.clip_max);
            try writeByteHashed(w, &hasher, if (st.grad_mean) 1 else 0);

            try writeTensorDataV4(w, &hasher, &st.s_weight);
            try writeTensorDataV4(w, &hasher, &st.t_weight);
            try writeTensorDataV4(w, &hasher, &st.s_bias);
            try writeTensorDataV4(w, &hasher, &st.t_bias);
        }

        try w.writeInt(u32, hasher.final(), .little);
        try buffered.flush();
        try file.sync();
        file.close();
        file_closed = true;

        try parent_dir.rename(tmp_name, base_name);
        try parent_dir.sync();
    }

    pub fn load(allocator: Allocator, path: []const u8) !RSF {
        return loadWithConfig(allocator, path, null);
    }

    pub fn loadWithConfig(allocator: Allocator, path: []const u8, policy: ?RSFConfig) !RSF {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();

        var r = file.reader();

        var magic: [4]u8 = undefined;
        try r.readNoEof(&magic);
        if (!std.mem.eql(u8, &magic, "RSF0")) return error.BadFileFormat;

        const version = try r.readInt(u32, .little);
        if (version != 1 and version != 2 and version != 3 and version != SAVE_VERSION) return error.UnsupportedVersion;

        const num_layers_u64 = try r.readInt(u64, .little);
        const dim_u64 = try r.readInt(u64, .little);
        if (num_layers_u64 == 0) return error.InvalidLayerCount;
        if (dim_u64 == 0) return error.InvalidDimension;

        const effective_max_dim: u64 = if (policy) |p| @intCast(p.max_dim) else (1 << 20);
        const effective_max_layers: u64 = if (policy) |p| @intCast(p.max_layers) else (1 << 20);
        if (num_layers_u64 > effective_max_layers or dim_u64 > effective_max_dim) return error.TooLarge;

        const num_layers = try checkedCastU64ToUsize(num_layers_u64);
        const dim = try checkedCastU64ToUsize(dim_u64);

        const global_clip_min: f32 = @bitCast(try r.readInt(u32, .little));
        const global_clip_max: f32 = @bitCast(try r.readInt(u32, .little));
        const global_grad_mean = (try r.readByte()) != 0;

        if (!std.math.isFinite(global_clip_min) or !std.math.isFinite(global_clip_max)) return error.InvalidConfig;
        if (!(global_clip_min < global_clip_max)) return error.InvalidConfig;
        if (global_clip_max > 20.0 or global_clip_min < -20.0) return error.InvalidConfig;

        var load_max_dim: usize = if (policy) |p| p.max_dim else (1 << 20);
        var load_max_layers: usize = if (policy) |p| p.max_layers else (1 << 20);

        var saved_max_dim_u64: u64 = @intCast(load_max_dim);
        var saved_max_layers_u64: u64 = @intCast(load_max_layers);
        if (version >= 2) {
            saved_max_dim_u64 = try r.readInt(u64, .little);
            saved_max_layers_u64 = try r.readInt(u64, .little);
            if (policy == null) {
                load_max_dim = @max(load_max_dim, @as(usize, @intCast(@min(saved_max_dim_u64, @as(u64, std.math.maxInt(usize))))));
                load_max_layers = @max(load_max_layers, @as(usize, @intCast(@min(saved_max_layers_u64, @as(u64, std.math.maxInt(usize))))));
            }
        }

        try validateRSFConfig(dim, num_layers, .{
            .clip_min = global_clip_min,
            .clip_max = global_clip_max,
            .grad_mean = global_grad_mean,
            .max_dim = load_max_dim,
            .max_layers = load_max_layers,
        });

        var rsf = try RSF.initWithConfig(allocator, dim, num_layers, .{
            .clip_min = global_clip_min,
            .clip_max = global_clip_max,
            .grad_mean = global_grad_mean,
            .max_dim = load_max_dim,
            .max_layers = load_max_layers,
        });
        errdefer rsf.deinit();

        const c = rsf.ctrl orelse return error.NotInitialized;

        var hasher = std.hash.Crc32.init();
        if (version == SAVE_VERSION) {
            hashBytes(&hasher, "RSF0");
            hashIntLE(u32, &hasher, version);
            hashIntLE(u64, &hasher, num_layers_u64);
            hashIntLE(u64, &hasher, dim_u64);
            hashF32Bits(&hasher, global_clip_min);
            hashF32Bits(&hasher, global_clip_max);
            hashByte(&hasher, if (global_grad_mean) 1 else 0);
            hashIntLE(u64, &hasher, saved_max_dim_u64);
            hashIntLE(u64, &hasher, saved_max_layers_u64);
        } else if (version >= 2) {
            hashF32Bits(&hasher, global_clip_min);
            hashF32Bits(&hasher, global_clip_max);
            hashByte(&hasher, if (global_grad_mean) 1 else 0);
        }

        var i: usize = 0;
        while (i < num_layers) : (i += 1) {
            const layer_clip_min: f32 = @bitCast(try r.readInt(u32, .little));
            const layer_clip_max: f32 = @bitCast(try r.readInt(u32, .little));
            const layer_grad_mean = (try r.readByte()) != 0;

            if (!std.math.isFinite(layer_clip_min) or !std.math.isFinite(layer_clip_max)) return error.InvalidConfig;
            if (!(layer_clip_min < layer_clip_max)) return error.InvalidConfig;
            if (layer_clip_max > 20.0 or layer_clip_min < -20.0) return error.InvalidConfig;

            if (version == SAVE_VERSION) {
                hashF32Bits(&hasher, layer_clip_min);
                hashF32Bits(&hasher, layer_clip_max);
                hashByte(&hasher, if (layer_grad_mean) 1 else 0);
            } else if (version >= 2) {
                hashF32Bits(&hasher, layer_clip_min);
                hashF32Bits(&hasher, layer_clip_max);
                hashByte(&hasher, if (layer_grad_mean) 1 else 0);
            }

            var s_w = try readTensorData(allocator, &r, version, &hasher);
            errdefer s_w.deinit();
            var t_w = try readTensorData(allocator, &r, version, &hasher);
            errdefer t_w.deinit();
            var s_b = try readTensorData(allocator, &r, version, &hasher);
            errdefer s_b.deinit();
            var t_b = try readTensorData(allocator, &r, version, &hasher);
            errdefer t_b.deinit();

            try validateTensorShape2D(&s_w, dim, dim);
            try validateTensorShape2D(&t_w, dim, dim);
            try validateTensorShape2D(&s_b, 1, dim);
            try validateTensorShape2D(&t_b, 1, dim);
            try validateFiniteSlice(s_w.data);
            try validateFiniteSlice(t_w.data);
            try validateFiniteSlice(s_b.data);
            try validateFiniteSlice(t_b.data);

            const st = try c.layers[i].withStateLocked();
            defer unlockPtr(&st.mutex);

            st.s_weight.deinit();
            st.t_weight.deinit();
            st.s_bias.deinit();
            st.t_bias.deinit();

            st.s_weight = s_w;
            st.t_weight = t_w;
            st.s_bias = s_b;
            st.t_bias = t_b;
            st.clip_min = layer_clip_min;
            st.clip_max = layer_clip_max;
            st.grad_mean = layer_grad_mean;

            if (st.s_weight_grad) |*g| zeroSlice(g.data);
            if (st.t_weight_grad) |*g| zeroSlice(g.data);
            if (st.s_bias_grad) |*g| zeroSlice(g.data);
            if (st.t_bias_grad) |*g| zeroSlice(g.data);
        }

        if (version >= 2) {
            const stored_checksum = try r.readInt(u32, .little);
            if (stored_checksum != hasher.final()) return error.ChecksumMismatch;
        }

        var eof_buf: [1]u8 = undefined;
        const extra = try r.read(&eof_buf);
        if (extra != 0) return error.TrailingData;

        const c_locked = try rsf.beginExclusive();
        defer endExclusive(c_locked);
        c_locked.cfg.clip_min = global_clip_min;
        c_locked.cfg.clip_max = global_clip_max;
        c_locked.cfg.grad_mean = global_grad_mean;
        c_locked.cfg.max_dim = load_max_dim;
        c_locked.cfg.max_layers = load_max_layers;

        return rsf;
    }
};

fn writeBytesHashed(w: anytype, hasher: *std.hash.Crc32, bytes: []const u8) !void {
    try w.writeAll(bytes);
    hasher.update(bytes);
}

fn writeByteHashed(w: anytype, hasher: *std.hash.Crc32, v: u8) !void {
    try w.writeByte(v);
    hashByte(hasher, v);
}

fn writeIntHashed(comptime T: type, w: anytype, hasher: *std.hash.Crc32, v: T) !void {
    try w.writeInt(T, v, .little);
    hashIntLE(T, hasher, v);
}

fn writeF32BitsHashed(w: anytype, hasher: *std.hash.Crc32, v: f32) !void {
    const bits: u32 = @bitCast(v);
    try w.writeInt(u32, bits, .little);
    hashIntLE(u32, hasher, bits);
}

fn hashBytes(hasher: *std.hash.Crc32, bytes: []const u8) void {
    hasher.update(bytes);
}

fn hashByte(hasher: *std.hash.Crc32, v: u8) void {
    hasher.update(&.{v});
}

fn hashIntLE(comptime T: type, hasher: *std.hash.Crc32, v: T) void {
    var le = std.mem.nativeToLittle(T, v);
    hasher.update(std.mem.asBytes(&le));
}

fn hashF32Bits(hasher: *std.hash.Crc32, v: f32) void {
    const bits: u32 = @bitCast(v);
    hashIntLE(u32, hasher, bits);
}

fn writeTensorDataV4(w: anytype, hasher: *std.hash.Crc32, t: *const Tensor) !void {
    try validateTensor2D(t);
    try validateFiniteSlice(t.data);

    const rank: u64 = 2;
    const d0: u64 = @intCast(t.shape.dims[0]);
    const d1: u64 = @intCast(t.shape.dims[1]);

    try writeIntHashed(u64, w, hasher, rank);
    try writeIntHashed(u64, w, hasher, d0);
    try writeIntHashed(u64, w, hasher, d1);

    for (t.data) |v| {
        const bits: u32 = @bitCast(v);
        try w.writeInt(u32, bits, .little);
        hashIntLE(u32, hasher, bits);
    }
}

fn readTensorData(allocator: Allocator, r: anytype, version: u32, hasher: *std.hash.Crc32) !Tensor {
    const rank = try r.readInt(u64, .little);
    if (rank != 2) return error.BadFileFormat;

    const d0_u64 = try r.readInt(u64, .little);
    const d1_u64 = try r.readInt(u64, .little);

    if (version == SAVE_VERSION) {
        hashIntLE(u64, hasher, rank);
        hashIntLE(u64, hasher, d0_u64);
        hashIntLE(u64, hasher, d1_u64);
    }

    const d0 = try checkedCastU64ToUsize(d0_u64);
    const d1 = try checkedCastU64ToUsize(d1_u64);
    var shape = [_]usize{ d0, d1 };
    var t = try Tensor.init(allocator, &shape);
    errdefer t.deinit();

    const expected = try checkedMul(d0, d1);
    if (t.data.len != expected) return error.DataLengthMismatch;

    var i: usize = 0;
    while (i < expected) : (i += 1) {
        const bits = try r.readInt(u32, .little);
        t.data[i] = @bitCast(bits);
        if (version >= 2) {
            hashIntLE(u32, hasher, bits);
        }
    }

    return t;
}

fn bytesToHexLower(out: *[32]u8, input: *const [16]u8) void {
    const alphabet = "0123456789abcdef";
    var i: usize = 0;
    while (i < input.len) : (i += 1) {
        const b = input[i];
        out[i * 2] = alphabet[(b >> 4) & 0x0f];
        out[i * 2 + 1] = alphabet[b & 0x0f];
    }
}
